// 1. AI 응답 및 사용자 원문 수신
const rawText = $input.first().json.output || "검색된 결과가 없습니다.";
let userQuery = "";

try {
  userQuery = $('Webhook-kakao channel').first().json.body.userRequest.utterance || "";
} catch(e) {
  userQuery = "";
}

// 2. 마크다운 및 특수문자 정제
const cleanText = rawText
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/\*(.*?)\*/g, '$1')
  .replace(/#+\s?/g, '')
  .replace(/`/g, '')
  .trim();

// 3. 업소 정보 정밀 파싱
const items = [];
const blocks = cleanText.split(/(?=\n?\d+\.\s*)/).filter(b => b.trim().length > 0);

blocks.forEach(block => {
  const trimmedBlock = block.trim();
  if (!/^\d+\.\s*/.test(trimmedBlock)) return;

  const lines = trimmedBlock.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  if (lines.length === 0) return;

  let title = lines[0].replace(/^\d+\.\s*/, '').replace(/[\*\_]/g, '').trim();
  title = title.split(/\s*-\s*(주소|전화|웹|TEL|Web):/i)[0].trim();

  let address = "";
  let phone = "";
  let web = "";

  const addrMatch = trimmedBlock.match(/(?:주소|Address):\s*([^\n\-]+)/i);
  if (addrMatch) address = addrMatch[1].trim();

  const phoneMatch = trimmedBlock.match(/(?:전화|TEL|Phone):\s*([^\n\-]+)/i);
  if (phoneMatch) {
    const rawPhone = phoneMatch[1].trim();
    if (!rawPhone.includes("없음") && !rawPhone.includes("N/A")) {
      phone = rawPhone;
    }
  }

  const webMatch = trimmedBlock.match(/(?:웹|Web|URL|사이트):\s*(https?:\/\/[^\s\n\-]+)/i) || trimmedBlock.match(/(https?:\/\/[^\s\n\-]+)/i);
  if (webMatch) web = webMatch[1].trim();

  if (title) {
    items.push({
      title: title,
      description: address || "토론토",
      phone: phone,
      web: web
    });
  }
});

// 4. Carousel (textCard) 구성
let templateOutputs = [];

if (items.length > 0) {
  const cards = items.slice(0, 5).map(item => {
    const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(item.description)}`;

    const buttons = [
      {
        action: "webLink",
        label: "📍 지도",
        webLinkUrl: mapUrl
      }
    ];

    if (item.phone) {
      buttons.push({
        action: "phone",
        label: "📞 전화",
        phoneNumber: item.phone.replace(/[^0-9]/g, '')
      });
    }

    if (item.web) {
      buttons.push({
        action: "webLink",
        label: "🌐 Web",
        webLinkUrl: item.web
      });
    }

    let cardDesc = `📍 주소: ${item.description}`;
    if (item.phone) cardDesc += `\n📞 전화: ${item.phone}`;

    return {
      title: item.title,
      description: cardDesc,
      buttons: buttons
    };
  });

  templateOutputs.push({
    carousel: {
      type: "textCard",
      items: cards
    }
  });

  if (cards.length > 1) {
    templateOutputs.push({
      simpleText: {
        text: "💡 카드를 옆으로 넘기시면 더 많은 검색 결과를 보실 수 있습니다."
      }
    });
  }

} else {
  templateOutputs.push({
    simpleText: {
      text: cleanText
    }
  });
}

// 5. 지역 미입력("유학원" 등) 시 감지 및 동적 연관 질문(Quick Replies) 제어

// 5-1. 지역 키워드 존재 여부 체크
let detectedLoc = "";
if (userQuery.includes("핀치")) detectedLoc = "핀치역";
else if (userQuery.includes("노스욕")) detectedLoc = "노스욕";
else if (userQuery.includes("다운타운")) detectedLoc = "다운타운";
else if (userQuery.includes("영앤블루어")) detectedLoc = "영앤블루어";

// 검색어에서 순수 업종/키워드 추출 (예: "유학원")
const cleanKeyword = userQuery.replace(/(토론토|핀치|노스욕|다운타운|근처|추천|지역)/g, '').trim() || "업소";

let dynamicQuickReplies = [];

if (!detectedLoc) {
  // [지역명이 입력되지 않은 경우] -> 주요 지역별 재검색 버튼 분기 제공
  dynamicQuickReplies = [
    { label: `📍 핀치근처 ${cleanKeyword}`, action: "message", messageText: `핀치역 근처 ${cleanKeyword}` },
    { label: `📍 노스욕 ${cleanKeyword}`, action: "message", messageText: `노스욕 ${cleanKeyword}` },
    { label: `📍 다운타운 ${cleanKeyword}`, action: "message", messageText: `다운타운 ${cleanKeyword}` },
    { label: `⭐ 후기 좋은 ${cleanKeyword}`, action: "message", messageText: `토론토 가장 후기 좋은 ${cleanKeyword}` }
  ];
} else {
  // [지역명이 명시된 경우] -> 업종 맞춤 2차 연관 질문 제공
  const loc = detectedLoc;
  if (/(유학원|유학|비자|유학원추천)/.test(userQuery)) {
    dynamicQuickReplies = [
      { label: `📄 ${loc} 학생비자/컬리지 상담`, action: "message", messageText: `${loc} 학생비자 컬리지 유학원` },
      { label: `💼 ${loc} 조기유학 전문`, action: "message", messageText: `${loc} 조기유학 전문 유학원` },
      { label: `⭐ ${loc} 가장 후기 좋은 유학원`, action: "message", messageText: `${loc} 후기 좋은 유학원` }
    ];
  } else if (/(부동산|콘도|렌트|매매)/.test(userQuery)) {
    dynamicQuickReplies = [
      { label: `🏠 ${loc} 콘도 렌트 시세`, action: "message", messageText: `${loc} 콘도 렌트 시세` },
      { label: `⚖️ ${loc} 한인 부동산 변호사`, action: "message", messageText: `${loc} 근처 한인 부동산 변호사` },
      { label: `🛠️ ${loc} 홈 인스펙션`, action: "message", messageText: `${loc} 근처 홈 인스펙션` }
    ];
  } else {
    dynamicQuickReplies = [
      { label: `⭐ ${loc} 추천 ${cleanKeyword}`, action: "message", messageText: `${loc} 추천 ${cleanKeyword}` },
      { label: `🅿️ ${loc} 주차 가능`, action: "message", messageText: `${loc} 주차 가능한 ${cleanKeyword}` },
      { label: `🕒 ${loc} 영업중인 곳`, action: "message", messageText: `${loc} 영업중인 ${cleanKeyword}` }
    ];
  }
}

// 6. 카카오 규격 반환
return {
  json: {
    version: "2.0",
    template: {
      outputs: templateOutputs,
      quickReplies: dynamicQuickReplies
    }
  }
};

return $input.all().map(item => {
  return {
    json: {
      id: item.json._id,
      name: item.json.name || null,
      category: item.json.category || null,
      address: item.json.address || null,
      contact: item.json.contact || null,
      about: item.json.about || null,
      website: item.json.website || null,
      imageurl: item.json.imageUrl || null,
      isactive: item.json.isActive ?? false,
      ispopular: item.json.isPopular ?? false,
      kakaoaccount: item.json.kakaoAccount || null,
      useremail: item.json.userEmail || null,
      createddate: item.json.createdDate || null,
      updatedate: item.json.updateDate || null
    }
  };
});

let results = [];
for (let item of $input.all()) {
  let text = `${item.json.name || ''} ${item.json.category || ''} ${item.json.address || ''} ${item.json.about || ''}`.trim();
  results.push({
    json: {
      id: item.json.id,
      combined_text: text,
      body: {
        input: text,
        model: "text-embedding-3-small"
      }
    }
  });
}
return results;

